def clean(n):
    n = n.strip().strip(",.")
    return n

def build():
    seen, out = set(), []
    for g, lst in (("m", MALE), ("f", FEMALE)):
        for n in lst:
            n = clean(n)
            if len(n) < 2: continue
            k = n.lower()
            if k in seen: continue
            seen.add(k); out.append((k, n, g))
    return out

if __name__ == "__main__":
    names = build()
    print(len(names), "unique;", sum(1 for _,_,g in names if g=='m'), "male,", sum(1 for _,_,g in names if g=='f'), "female")
